## Setup ----
# Load or prepare any necessary data for testing

## IO correctness ----
test_that("rcpp population interface works with correct inputs", {
  # setup population to create test values
  population <- methods::new(Population)
  n_years <- 10
  n_ages <- 10
  log_M_length <- n_years * n_ages
  population$log_M[] <- rep(-1, log_M_length)

  population$log_init_naa[] <- rep(0, n_ages)

  population$log_init_naa$set_estimation_types(c("fixed_effects"))
  population$n_ages$set(n_ages)
  population$ages[] <- seq(1, n_ages)
  population$n_fleets$set(2)
  population$n_years$set(n_years)


  #' @description Test that the population id is 1.
  expect_equal(
    object = population$get_id(),
    expected = 1
  )

  for (i in 1:(n_years * n_ages)) {
    #' @description Test that the log_M values are all -1.
    expect_equal(
      object = population$log_M[i]$value,
      expected = -1
    )
    #' @description Test that the log_M values are not estimated.
    expect_equal(
      object = population$log_M[i]$estimation_type$get(), "constant"
    )
  }

  for (i in 1:n_years) {
    #' @description Test that the log_init_naa values are all 0.
    expect_equal(
      object = population$log_init_naa[i]$value,
      expected = 0
    )
    #' @description Test that the log_init_naa values are estimated.
    expect_equal(
      object = population$log_init_naa[i]$estimation_type$get(), "fixed_effects"
    )
  }

  population$log_init_naa$set_estimation_types(c("constant"))
  population$log_M$set_estimation_types(c("fixed_effects"))

  for (i in 1:(n_years * n_ages)) {
    #' @description Test that the log_M values are all -1.
    expect_equal(
      object = population$log_M[i]$value,
      expected = -1
    )
    #' @description Test that the log_M values are now estimated.
    expect_equal(
      object = population$log_M[i]$estimation_type$get(), "fixed_effects"
    )
  }

  for (i in 1:n_years) {
    #' @description Test that the log_init_naa values are all 0.
    expect_equal(
      object = population$log_init_naa[i]$value,
      expected = 0
    )
    #' @description Test that the log_init_naa values not estimated.
    expect_equal(
      object = population$log_init_naa[i]$estimation_type$get(), "constant"
    )
  }

  #' @description Test that SetName/GetName round trip correctly for Population.
  expect_silent(population$SetName("test_population"))
  expect_equal(population$GetName(), "test_population")

  #' @description Test that linking module IDs and fleet IDs in Population is silent.
  maturity <- methods::new(LogisticMaturity)
  growth <- methods::new(EWAAGrowth)
  recruitment <- methods::new(BevertonHoltRecruitment)
  fleet <- methods::new(Fleet)
  expect_silent(population$SetMaturityID(maturity$get_id()))
  expect_silent(population$SetGrowthID(growth$get_id()))
  expect_silent(population$SetRecruitmentID(recruitment$get_id()))
  expect_silent(population$AddFleet(fleet$get_id()))

  clear()
})

